import socket, struct, random
def dns_lookup(name, server=('127.0.0.11',53), qtype=1):
    qid = random.randint(0,65535)
    header = struct.pack('>HHHHHH', qid, 0x0100, 1, 0, 0, 0)
    qname = b''.join(bytes([len(p)])+p.encode() for p in name.split('.'))+b'\x00'
    query = header + qname + struct.pack('>HH', qtype, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
    try:
        s.sendto(query, server)
        data, _ = s.recvfrom(512)
        ancount = struct.unpack('>H', data[6:8])[0]
        answers=[]
        if ancount:
            off=12
            while data[off]!=0: off+=1+data[off]
            off+=5
            for _ in range(ancount):
                while off < len(data):
                    l=data[off]
                    if l==0: off+=1; break
                    elif l&0xC0==0xC0: off+=2; break
                    else: off+=1+l
                rtype, rclass, ttl, rdlen = struct.unpack('>HHIH', data[off:off+10]); off+=10
                if rtype==1 and rdlen==4:
                    answers.append('.'.join(str(b) for b in data[off:off+4]))
                off+=rdlen
        return ancount, answers
    except Exception as e:
